  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "Given a single Phase 3 oncology asset in the US with potential accelerated approval, what are the key clinical program risks that should be quantified for valuation purposes, and how can milestone payments be calibrated to reflect these risks?",
    "legal": "What legal considerations arise from assigning US territorial rights to the biotech and EU/UK rights to the pharma, particularly regarding IP ownership, regulatory approvals under FDA accelerated pathways, and post-Brexit EU/UK patent enforcement?",
    "finance": "How should a financial model be constructed for this co-development deal, including rNPV calculation, milestone payment schedule design, tiered royalty structure, and overall deal economics to balance upside potential with risk sharing?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "Potentially stale FDA accelerated approval guidance updates, post-Brexit EU/UK regulatory changes, recent IP litigation trends."
}
